            if ((cpu->p & NH_P_Z) == 0u) {
                cpu->pbr = 0xC7u;
                cpu->pc = 0x86FDu;
                if (nh_scpu_expect_next(cpu, 0x063C37E8u) != NH_SCPU_EXECUTED)
                    return NH_SCPU_STOPPED;
                return nh_scpu_finish(cpu, bus, 3u);
            }
            cpu->pbr = 0xC7u;
            cpu->pc = 0x86FAu;
            if (nh_scpu_expect_next(cpu, 0x063C37D0u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
            return nh_scpu_finish(cpu, bus, 2u);
